#pragma once

#include <cstdint>
#include <memory>
#include <optional>
#include <string>
#include <string_view>
#include <vector>

#include <cppfrontier/ast.hpp>
#include <cppfrontier/diagnostic.hpp>
#include <cppfrontier/token.hpp>

namespace cppfrontier {

struct symbol final {
    symbol_id id = invalid_symbol;
    std::string name;
    declaration_kind kind = declaration_kind::object;
    symbol_id parent = invalid_symbol;
    std::uint32_t declaration_order = 0;
    // The declared type; a function's return type.
    type_id type;
    source_span span;
    // Generated by a metafunction or the translator, not declared in the source.
    bool generated = false;
};

struct symbol_reference final {
    symbol_id symbol = invalid_symbol;
    source_span span;
};

struct ir_declaration final : declaration_signature {
    enum class special_member_kind : std::uint8_t {
        none,
        default_constructor,
        defaulted_default_constructor,
        user_default_constructor,
        copy_constructor,
        move_constructor,
        // Any other `operator=: (out this, ...)`.
        converting_constructor,
        copy_assignment,
        move_assignment,
        // Any other `operator=: (inout this, ...)`.
        converting_assignment,
        destructor,
        deleted_copy_constructor,
        deleted_copy_assignment,
    };

    struct member_initializer final {
        std::string member;
        std::string value;
        // `member` is a base type.
        bool is_base = false;
        // The leading body statement `member = value;` that this replaces.
        std::optional<statement_id> source;
        // A base set from `that` is moved from it.
        bool move_that = false;
    };

    symbol_id symbol = invalid_symbol;
    source_span span;
    std::vector<ir_declaration> members;
    std::string alias;
    std::string using_name;
    // An object's initializer, or a function's single-expression body.
    parsed_expression body;
    // A generated function's Cpp1 block body, emitted verbatim.
    std::string cpp1_body;
    std::vector<member_initializer> member_initializers;
    // A data member declared before a base lives in this helper base, so the
    // two are initialized in declaration order.
    std::string base_helper;
    // Leading body statements already lowered into `member_initializers`.
    std::size_t initializer_statements = 0;
    // The Cpp2 text of members `@autodiff` generated, for `@print`. Each is
    // inserted before the source member at `before`, or else at the end.
    struct generated_member final {
        std::string text;
        std::optional<source_position> before;
    };
    std::vector<generated_member> generated_members;
    // Cpp1 text emitted verbatim for a generated member, such as the `@enum` conversion.
    std::string cpp1_text;
    // Cpp1 text emitted after every function definition, in the namespace
    // enclosing the declaration, such as the `static_assert` of `@impl`.
    std::string trailing_cpp1;
    // `member = value;` statements emitted before the body of an assignment.
    std::vector<member_initializer> that_assignments;
    // The cases of a closed sum type, which an inspect covering each needs no
    // `is _`: the case types of an `@adt`, the enumerators of an `@enum`, or
    // the derived types of a `@sealed` type.
    std::vector<symbol_id> sum_cases;
    std::string special_member_owner;
    // Immutable; members generated by reflection share their source member's body.
    std::shared_ptr<const function_body> function_statements;
    // Set for each `operator=` of a type by reflection, which keys special
    // members by this rather than by name.
    special_member_kind special_member = special_member_kind::none;
    bool is_static_function = false;
    bool is_generated = false;
    // A converting constructor declared `explicit`, as `@newtype` generates it.
    bool is_explicit = false;
    // Declared directly inside a type.
    bool is_type_member = false;
    // An `operator++` or `operator--` of a type that has no copy constructor,
    // so it gets no Cpp1 postfix form.
    bool omits_postfix = false;
    // A generated type defined after every other type definition and function
    // declaration, so that its definition sees functions declared anywhere.
    bool is_defined_last = false;
};

// The leading body statement of `function` that `initializer` replaces, if any.
[[nodiscard]] inline auto initializer_statement(
    const ir_declaration& function, const ir_declaration::member_initializer& initializer)
    -> const statement* {
    if (!initializer.source || !function.function_statements) return nullptr;
    for (const auto& value : function.function_statements->statements) {
        if (value->id == *initializer.source) return value.get();
    }
    return nullptr;
}

// A constructor, from a Cpp2 `operator=: (out this, ...)` or generated.
[[nodiscard]] inline auto is_constructor(const ir_declaration& declaration) noexcept -> bool {
    using kind = ir_declaration::special_member_kind;
    switch (declaration.special_member) {
    case kind::default_constructor:
    case kind::defaulted_default_constructor:
    case kind::user_default_constructor:
    case kind::copy_constructor:
    case kind::move_constructor:
    case kind::converting_constructor:
    case kind::deleted_copy_constructor:
        return true;
    default:
        return false;
    }
}

// An assignment, from a Cpp2 `operator=: (inout this, ...)` or generated, and not deleted.
[[nodiscard]] inline auto is_assignment(const ir_declaration& declaration) noexcept -> bool {
    using kind = ir_declaration::special_member_kind;
    return declaration.special_member == kind::copy_assignment ||
        declaration.special_member == kind::move_assignment ||
        declaration.special_member == kind::converting_assignment;
}

// How a function's result type is determined.
enum class return_form : std::uint8_t {
    implicit_void,           // no `->` and no expression body
    implicit_deduced,        // no `->` and an expression body: `decltype(auto)`
    deduced_value,           // `-> _`: `auto`
    deduced_forwarding,      // `-> forward _`: `decltype(auto)`
    deduced_forwarding_ref,  // `-> forward_ref _`: `auto&&`
    declared,                // `-> T`, including `-> void` and named return values
    declared_forwarding,     // `-> forward T`: a reference to `T`
};

[[nodiscard]] inline auto return_form_of(const ir_declaration& declaration) noexcept
    -> return_form {
    switch (declaration.deduction) {
    case return_deduction::by_value: return return_form::deduced_value;
    case return_deduction::by_forwarding: return return_form::deduced_forwarding;
    case return_deduction::by_forwarding_ref: return return_form::deduced_forwarding_ref;
    case return_deduction::by_forwarding_typed: return return_form::declared_forwarding;
    case return_deduction::none: break;
    }
    if (!declaration.type.is_wildcard()) return return_form::declared;
    return declaration.body.empty() ? return_form::implicit_void : return_form::implicit_deduced;
}

// The names the translator generates begin with this prefix, which Cpp2 code
// may not use.
inline constexpr auto generated_name_prefix = std::string_view{"__cpp2_"};

[[nodiscard]] inline auto is_function_expression_name(std::string_view name) -> bool {
    return name.starts_with("__cpp2_function_expression_");
}

// An unnamed function expression, parsed as the function declaration `name`
// and lowered as a lambda wherever `name` appears.
struct function_expression final {
    struct capture final {
        std::string name;
        parsed_expression expression;
    };
    std::string name;
    // `x$` in the body is the capture `_0 = x`.
    std::vector<capture> captures;
};

struct ir_program final {
    std::vector<symbol> symbols;
    std::vector<ir_declaration> declarations;
    std::vector<symbol_reference> references;
    std::vector<function_expression> function_expressions;
};

// Appends a symbol; ids are dense, so symbol `n` is `program.symbols[n - 1]`.
[[nodiscard]] auto add_symbol(ir_program& program, symbol value) -> symbol_id;

[[nodiscard]] inline auto find_symbol(const ir_program& program, symbol_id id) noexcept
    -> const symbol* {
    if (id == invalid_symbol || id > program.symbols.size()) return nullptr;
    const auto& found = program.symbols[id - 1];
    return found.id == id ? &found : nullptr;
}

}
